/* Ім'я людини: або готове з книги, або випадкове «ім'я + прізвисько» */
function humanName(cat){
  const fem = cat === 'women'
  if(Math.random() < 0.25) return pick(names[cat])
  const first = pick(firstNames[cat])
  if(Math.random() < 0.6) return `${first} ${pick(nickNouns)}`
  const adj = pick(nickAdj)[fem ? 1 : 0]
  return Math.random() < 0.5 ? `${adj} ${first}` : `${first} ${adj}`
}
function oneName(cat){ return (cat === 'men' || cat === 'women') ? humanName(cat) : pick(names[cat]) }

/* ГЕНЕРАТОРИ */
function generateAward(){
  const type=document.getElementById('awardType').value;
  const r=d(10);
  document.getElementById('awardsOut').textContent = `Тип: ${type==='small'?'Мала':type==='medium'?'Середня':'Велика'}\n— ${awards[type][r]}`;
}
function generateJobAward(){
  const level=document.getElementById('jobLevel').value;
  const r=d(6);
  const label= level==='light'?'Легка': (level==='mid'?'Середня':'Важка');
  document.getElementById('jobAwardsOut').textContent = `Справa: ${label}\n— ${jobAwards[level][r]}`;
}

/* Випадковий елемент зі списку (для 6×6 попередньо розгорнутого масиву) */
function pick(list){ return list[Math.floor(Math.random()*list.length)]; }
function roll2d6Table(key, outId){
  const map={cargo,places,hazards,themes,people};
  document.getElementById(outId).textContent = pick(map[key]);
}

function generateRaiders(){
  const a = pick(raiders.what);
  const b = pick(raiders.who);
  const c = pick(raiders.detail);
  const dL = pick(raiders.leader);
  const out = `Назва: ${a} ${b}\nДеталь: ${c}\nЛідер: ${dL}`;
  document.getElementById('raidersOut').textContent = out;
}

function generateEpithet(){
  const type=document.getElementById('epitType').value;
  const word= pick(epithets[type]);
  const label={tech:"Технологія",weapon:"Зброя",armor:"Броня",enemy:"Ворог",npc:"НІП",place:"Місце"}[type];
  document.getElementById('epitOut').textContent = `${label}: ${word}`;
}

function generateName(){
  const cat=document.getElementById('namesCat').value;
  const n=Math.max(1, Math.min(10, parseInt((document.getElementById('namesCount')||{}).value,10)||1));
  const out=new Set();
  for(let tries=0; out.size<n && tries<200; tries++) out.add(oneName(cat));
  document.getElementById('namesOut').textContent = [...out].join('\n');
}


/* Копіювання */
async function copyOut(id){
  const el = document.getElementById(id);
  const txt = (el && el.textContent ? el.textContent.trim() : "");
  if(!txt) return;

  const flash = () => {
    el.style.outline = `2px solid var(--brand)`;
    setTimeout(()=> el.style.outline = "", 650);
  };

  // 1) Спроба через сучасний Clipboard API в захищеному контексті
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(txt);
      flash();
      return;
    }
  } catch(e){ /* ігноруємо, підемо у фолбек */ }

  // 2) Фолбек через тимчасове <textarea>
  let ok = false;
  const ta = document.createElement("textarea");
  ta.value = txt;
  ta.setAttribute("readonly", "");
  ta.style.position = "fixed";
  ta.style.top = "-1000px";
  ta.style.opacity = "0";
  document.body.appendChild(ta);
  ta.focus();
  ta.select();
  try {
    ok = document.execCommand("copy");
  } catch(e) {
    ok = false;
  }
  document.body.removeChild(ta);
  if (ok) { flash(); return; }

  // 3) Останній шанс: виділити текст у блоці та спробувати скопіювати
  try {
    const range = document.createRange();
    range.selectNodeContents(el);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
    ok = document.execCommand("copy");
    sel.removeAllRanges();
    if (ok) { flash(); return; }
  } catch(e){ /* no-op */ }

  // Якщо всі способи провалилися — відкриємо нативний вибір тексту
  // (корисно для мобільних — користувач зможе вручну натиснути "Копіювати")
  try {
    const range = document.createRange();
    range.selectNodeContents(el);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
  } catch(e){ /* no-op */ }
}

